/**
 * `nx run contracts:generate`: writes the JSON Schema of every registry entry
 * to `generated/json-schema/<name>.schema.json`, then its Go type to
 * `apps/runner/internal/contracts/<name>.go` with go-jsonschema. Deterministic:
 * sorted keys, stable file order, stale generated files removed. The output
 * is committed; CI fails when running it leaves a diff.
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { z } from 'zod';
import { registry } from './registry.js';

const GO_JSONSCHEMA = 'github.com/atombender/go-jsonschema@v0.24.1';
const GO_HEADER = '// Code generated by github.com/atombender/go-jsonschema, DO NOT EDIT.';

const packageRoot = resolve(import.meta.dirname, '..');
const jsonSchemaDir = join(packageRoot, 'generated', 'json-schema');
const runnerRoot = resolve(packageRoot, '../../apps/runner');
const goDir = join(runnerRoot, 'internal', 'contracts');

export interface RegistryEntry {
  name: string;
  schema: z.ZodType;
}

/** `agent-session` → `AgentSession`: the title, hence the Go type's name. */
const typeName = (name: string): string =>
  name
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');

const sortKeys = (value: unknown, key?: string): unknown => {
  if (Array.isArray(value)) {
    const items = value.map((item) => sortKeys(item));
    return key === 'required' ? items.sort() : items;
  }
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([k, v]) => [k, sortKeys(v, k)]),
    );
  }
  return value;
};

export const renderJsonSchema = ({ name, schema }: RegistryEntry): string => {
  const jsonSchema = { ...z.toJSONSchema(schema, { target: 'draft-2020-12' }), title: typeName(name) };
  return `${JSON.stringify(sortKeys(jsonSchema), null, 2)}\n`;
};

const removeStale = (dir: string, keep: Set<string>, isGenerated: (file: string) => boolean): void => {
  for (const file of readdirSync(dir)) {
    if (!keep.has(file) && isGenerated(file)) rmSync(join(dir, file));
  }
};

const generate = (): void => {
  const entries = [...registry].sort((a, b) => (a.name < b.name ? -1 : 1));
  mkdirSync(jsonSchemaDir, { recursive: true });
  mkdirSync(goDir, { recursive: true });

  for (const entry of entries) {
    const schemaFile = join(jsonSchemaDir, `${entry.name}.schema.json`);
    writeFileSync(schemaFile, renderJsonSchema(entry));
    execFileSync(
      'go',
      ['run', GO_JSONSCHEMA, '--package', 'contracts', '--tags', 'json', '--struct-name-from-title', '--output', join(goDir, `${entry.name}.go`), schemaFile],
      { cwd: runnerRoot, stdio: 'inherit' },
    );
  }

  removeStale(jsonSchemaDir, new Set(entries.map((e) => `${e.name}.schema.json`)), (file) => file.endsWith('.schema.json'));
  removeStale(
    goDir,
    new Set(entries.map((e) => `${e.name}.go`)),
    (file) => file.endsWith('.go') && !file.endsWith('_test.go') && readFileSync(join(goDir, file), 'utf8').startsWith(GO_HEADER),
  );
  execFileSync('gofmt', ['-w', goDir], { stdio: 'inherit' });
};

if (import.meta.main) generate();
